mapper.select:
select count(*)
from ujcms_attachment t
where t.site_id_ = #{siteId}

    and t.created_ >= #{created}

select

from ujcms_attachment t
where t.url_ = #{url,jdbcType=VARCHAR}

mapper.update:
update ujcms_attachment
set shared_category_id_ = #{categoryId,jdbcType=BIGINT}
where id_ = #{id,jdbcType=BIGINT}

mapper.select:
select

from ujcms_attachment t
where t.id_ = #{id,jdbcType=BIGINT}

select

, c.name_ as shared_category_name_
from ujcms_attachment t
left join ujcms_resource_category c on c.id_ = t.shared_category_id_
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.shared_category_id_ is not null

    and t.shared_category_id_ = #{categoryId,jdbcType=BIGINT}


    and t.name_ like #{keyword,jdbcType=VARCHAR}


    and (
    t.name_ like #{ext}
    )

order by t.id_ desc

select

from ujcms_attachment t
inner join ujcms_attachment_favorite fav on fav.attachment_id_ = t.id_
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and fav.user_id_ = #{userId,jdbcType=BIGINT}


        and fav.category_id_ is null
        and fav.category_id_ = #{categoryId,jdbcType=BIGINT}



    and t.name_ like #{keyword,jdbcType=VARCHAR}


    and (
    t.name_ like #{ext}
    )

order by fav.created_ desc
